insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('999bda2b-2b88-4a84-bd9c-d736ccb07089', 'ja', '彼女が「マーケティングの仕事をしています」と言います。糸口をたどっている返しは、どれですか？', '["「いいですね。ご出身はどちらですか？」", "「友人にもマーケティングの人がいます。世間は狭いですね」", "「へえ、いいですね。こちらは金融の仕事です」", "「マーケティング、面白そうですね。どんな分野ですか？SNS、ブランド、それとも分析？」"]'::jsonb, '糸口をたどるとは、彼女の話題をさらに掘り下げることです。彼女が口にしたことについて、具体的に尋ねましょう。')
