insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2923827f-429f-4dd6-ac88-436a5a9dbbc6', 'ja', 'どの糸口をたどるかは、どう選ぶべきですか？', '["自分が興味を持てる内容をひとつ選ぶ", "あらかじめ用意した質問リストを使う", "彼女が話してくれた具体的な内容を広げる"]'::jsonb, '彼女が差し出すどんな内容も、会話を前に進められます。自分の好奇心が動くものを選びましょう。')
