insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('52edb21f-05cb-41ea-a94c-5ec38eca6a8d', 'ja', '質問にはできなくて、自分のひと言や観察にできることは何ですか？', '["自分の見方を伝えることで、自信を示す", "考えを話せるだけの面白さがある人だと示す", "答えを求めることなく、返すきっかけをつくる"]'::jsonb, '観察は、答える負担をかけずに、彼女に「返せるもの」を渡します。')
