insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('89a9c6b7-ea88-49ca-a0b1-19c9f94287cd', 'ja', '情報をもらうための質問ではなく、観察や自分のひと言になっている返しは、どれですか？', '["「その一杯、必要だったという顔ですね」", "「それは疲れそうですね」", "「いつも遅くまで働いているんですか？」", "「ここ、週末はすごく慌ただしくなりますよね」"]'::jsonb, 'これらは、さらに情報を求めるのではなく、状況や見方を差し出しています。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a8dcf867-454f-44e9-b824-f823389b43f0', 'ja', '健全な会話の流れを、最もよく表しているのはどれですか？', '["間を置かずに、自信を持って話すこと", "完全に彼女にリードを任せること", "沈黙を、できるだけ早く埋めること", "二人ともが加わる、安定したやり取り"]'::jsonb, '会話の流れは、話し続けることでも、完全に受け身になることでもなく、二人で差し出し合うことから生まれます。')
