insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3b838c1a-69b1-4328-9785-cd16d57ae3b6', 'ja', '彼女が最近の旅行の話をします。そこには自分も行ったことがあります。どう返せますか？', '["自分の旅行でしたことを、すべて話す", "「ええ、行ったことがあります」と言って、そこで終える", "ひと言だけ話してから、彼女に続きを促す"]'::jsonb, '短く差し出して、そのあと余白を残すと、会話の流れを二人で分かち合えます。')
