insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2760f510-bd8b-4ac3-bab9-6e67951fb689', 'ja', '会話を独占すると、なぜ彼女の気持ちが入らなくなるのですか？', '["彼女が加わることを妨げるから", "一方的な独演会になるから", "しっかり聞いていることを示すから"]'::jsonb, '独占すると、彼女の入る余地がなくなり、バランスの取れた会話の流れが崩れます。')
