insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6e149fa3-93c4-42b2-9c8e-f7f88712cc49', 'ja', '彼女が難しい決断について話し終え、こちらを見ます。一番良い返しはどれですか？', '["すぐに安心させる言葉をかける", "すぐにアドバイスをする", "少し間を置き、目を合わせたまま、それから応える", "雰囲気を軽くするために、話題を変える"]'::jsonb, '短い間は、彼女の言葉を受け取って考えていることを示し、話が深まるのを招きます。')
