insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f100da89-837b-4ce4-89f0-13a05418c184', 'ja', '考えさせる質問をします。彼女は答える前に考えています。どうするべきですか？', '["助け舟を出す", "質問を言い換える", "もうひとつ質問を足す", "その間を保ち、彼女に考えてもらう"]'::jsonb, 'プレッシャーをかけずに考えてもらうことは、忍耐と自信を示します。')
