insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('af284377-c4c0-42ca-a6f4-112ce777e549', 'ja', '会話の中で、沈黙が最も効果的なのはどんなときですか？', '["彼女が個人的なことを話してくれたあと", "何を言えばいいか分からないとき", "よく考えたひと言を口にする直前", "会話に加わることを、まったく避けるため"]'::jsonb, '沈黙が効くのは、考える余地を与えたり、重みを加えたりするときです。関わることの代わりにするときではありません。')
