insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5d75efc2-36fb-47a3-9f27-cb0833551415', 'ja', '会話における「言外のメッセージ」とは、何ですか？', '["口にされた言葉そのもの", "言葉の裏にある、気持ちの上での意味", "彼女の声の大きさだけ", "彼女の文の長さ"]'::jsonb, '言外のメッセージとは、口にされた言葉と、その裏にある気持ちとのあいだにあるすき間のことです。そこに応えましょう。')
