insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9fe24bb8-edce-4a11-ac05-37dcfca6822d', 'ja', '彼女が、静かで不安げなトーンで「最近こっちに引っ越してきたんです」と言います。思いやりのある返しは、どれですか？', '["「どちらから引っ越してきたんですか？」", "「今のところ、気に入っていますか？」", "「それは大変なこともありますよね。慣れるまで、どうでしたか？」", "「お仕事は何をしているんですか？」"]'::jsonb, 'この返しは、彼女のトーンににじんでいた気持ちの部分を受け止めています。')
