insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0af9f869-b543-4bea-bfe5-e3c0c0722302', 'ja', '彼女が「姉とは、もうあまり会えなくなってしまって」と言います。一番良い返しはどれですか？', '["「人生、そういうものですよ」", "「お姉さんは、おいくつですか？」", "「離れていると、つらいですよね。お二人は、よく話すんですか？」", "「お姉さんは、今どちらに住んでいるんですか？」"]'::jsonb, '尋ねる前に、そこにある気持ちを言葉にすると、その場が人間らしいものであり続けます。')
