insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6886b3ac-3f9a-4fba-ad87-515db908bb79', 'ja', '彼女が、最近の出来事について感情を込めて話します。まず何ができますか？', '["共感を持って、彼女の気持ちのトーンに合わせる", "実用的なアドバイスで応える", "笑えるエピソードに切り替える", "事実についての質問をする"]'::jsonb, '別の方向へ導く前に、彼女のトーンを映し返して、波長が合っていることを示しましょう。')
