insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c32cb2cd-cf15-4d66-aa1f-8bc019d02b51', 'ja', '会話の序盤です。彼女が「お仕事は何をしているんですか？」と尋ねます。その場に一番合っている返しは、どれですか？', '["「IT系の仕事ですが、嫌でたまらなくて。代わりに何がしたいのかも分からないんです」", "「IT系の仕事です。大変ですが、自分を律することをたくさん教わっています」", "「ちょっと複雑で。あまり話したくないんです」"]'::jsonb, 'この返しは、現実を認めながら、自分なりの見方を示しています。心配ではなく、好奇心を招きます。')
