insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('26a750bf-98fb-4c3c-a099-407b3b3aabb9', 'ja', '彼女が、今の仕事に就いたきっかけを尋ねます。何を話せますか？', '["高校から今までの、すべての経緯", "背景なしに、今の役割だけ", "分野を変えるきっかけになった、ひとつの大事な瞬間"]'::jsonb, '意味のあるひとつの瞬間に絞ると、人柄がはっきり伝わり、相手の関心も保てます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2330422b-5fb8-4763-a6cc-a1631f85f12d', 'ja', '注意を引きつけ続けるエピソードに欠かせない要素は、どれですか？', '["状況を手短に伝える導入", "かかっているものを生む、葛藤や緊張", "結末、または学び", "正確な日付と名前"]'::jsonb, '起きたことのすべてではなく、彼女に理解してほしいことに絞りましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1ce28b32-b0c8-4221-b1ff-d3645dd9b96d', 'ja', 'つなげないままのエピソードは、なぜつながりではなく隔たりを生むのですか？', '["自己中心的で、彼女に関心がないように見えるから", "彼女を引き入れずに、自分のことを話したから", "彼女が、こちらの話に関わる代わりに、自分の番を待っているから"]'::jsonb, 'つなげないまま話すと、距離が生まれます。彼女の見方を招いて、つながりを保ちましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3f38e00a-0c18-4520-94c4-258ed755d84d', 'ja', '彼女につなげている終わり方は、どれですか？こちらの話：「こっちに引っ越してきたとき、最初の数か月は孤独でした」', '["「まあ、結局うまくいったんですけどね」", "「あの街は、最初は大変ですよね」", "「引っ越しは、いつでも大変ですよね」", "「そちらは、ここまで慣れるのはどうでしたか？」"]'::jsonb, '彼女の見方を直接招くことで、自分の経験が、二人の共通の土台に変わります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d6f93781-4c91-4d3e-835b-28dd4c18773b', 'ja', '自分のエピソードを、どうすれば彼女につなげられますか？', '["話した状況で彼女ならどうするかを尋ねる", "彼女が前に話してくれたことと結びつける", "関係のある彼女の資質や見方を褒める"]'::jsonb, 'つながりは、自分の話が結論ではなく、橋になったときに生まれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('445fcfa0-4ff7-4518-ac38-f732d3f82c0a', 'ja', '彼女は個人的なことを進んで話し、よく笑います。これは何を示していますか？', '["礼儀正しくしているだけ", "次につなげる誘いを支えられるだけの重みが、つながりに生まれている", "こちらに立ち去ってほしいと思っている", "やり取りは、まだ表面的なまま"]'::jsonb, '進んで話してくれることと、そのエネルギーは、次につなげる機が熟したことを示しています。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('22126888-2232-418e-83ad-f3149c24f572', 'ja', '彼女の返事には温かさがあり、こちらの話を広げてくれます。これは何を示していますか？', '["次につなげる誘いを支えられるだけの重みが、つながりに生まれている", "会話に付き合ってくれているだけ", "短く済ませたいと思っている", "会話は、まだ表面的なまま"]'::jsonb, '温かさと、話を広げてくれることは、しっかり気持ちが入っているサインです。次につなげる機が熟しています。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8c9143a9-92d6-4ec0-bd1d-cc131e69c354', 'ja', '次につなげる機が熟したことを示す、主なサインは何ですか？', '["短く、礼儀正しい返事をする", "必要以上に、会話に加わってくれる", "こちらについて質問してくる", "その場に居続け、好奇心を見せ続ける"]'::jsonb, '彼女が気持ちを注ぎ、こちらについて尋ね、関わり続けているなら、次につなげる機が熟しています。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('372fbba5-b4e8-4738-9cf6-186872aed9ae', 'ja', '別れ際のひと言を、二人で話した内容に結びつけるべきなのは、なぜですか？', '["思慮深く聞こえるため", "また連絡する理由を、自然につくるため", "注意を払っていたことを証明するため", "すぐに惹かれる気持ちを高めるため"]'::jsonb, '二人で話した内容に結びつけると、また連絡を取る自然な理由が生まれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4bf82e54-bc68-47b4-954e-9a2f34ad7cee', 'ja', '彼女のこれからの旅行について、良い会話ができました。一番良い別れ方はどれですか？', '["「お会いできてよかったです。お元気で」", "「そろそろ、引き止めるのはやめておきますね」", "気まずさを避けるために、手早く別れを告げる", "旅行の話に触れて、またあとで続きを話そうと提案する"]'::jsonb, '彼女が大切にしていた話題にもう一度触れると、別れのあとも、やり取りが生き続けます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
